return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'hi_IN','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-02T07:33:51+00:00','po-revision-date'=>'2026-09-02T07:33:51+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'WordPress के लिए एक पूर्ण कैशिंग और अनुकूलन इंजन: पूर्ण-पेज कैश, ऑब्जेक्ट कैश, डेटाबेस क्लीनअप और CSS/JS अनुकूलन। इसे तब स्थापित करें जब आपका होस्ट अपना स्वयं का कैश लेयर प्रदान नहीं करता है — Zinn Digital® होस्टिंग पर इसके बजाय Zinn® Cache स्थापित करें। पूर्ण-पेज कैशिंग के लिए LSCache मॉड्यूल के साथ एक LiteSpeed या OpenLiteSpeed सर्वर की आवश्यकता होती है। LiteSpeed Cache प्लगइन का एक GPLv3 फोर्क।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d घंटे','%d hour'=>'%d घंटा','%d minutes'=>'%d मिनट','%d minute'=>'%d मिनट','Purged All!'=>'सभी को साफ़ कर दिया गया!','Purged the blog!'=>'ब्लॉग हटा दिया गया!','Purged the URL!'=>'यूआरएल को साफ़ कर दिया गया है!','Purged!'=>'साफ़ कर दिया गया!','Failed to upgrade.'=>'अपग्रेड करने में विफल।','Upgraded successfully.'=>'सफलतापूर्वक अपग्रेड किया गया।','Dashboard'=>'डैशबोर्ड','OptimaX'=>'ऑप्टिमाएक्स','Presets'=>'प्रीसेट','General'=>'सामान्य','Cache'=>'कैश','CDN'=>'सीडीएन','Image Optimization'=>'छवि अनुकूलन','Page Optimization'=>'पेज ऑप्टिमाइज़ेशन','Database'=>'डेटाबेस','Crawler'=>'क्रॉलर','Toolbox'=>'टूलबॉ